    "id": "HC-41",
    "slug": "review-translations-and-preserve-approved-wording",
    "title": "Review translations and preserve approved wording",
    "summary": "Review translated wording while preserving English and staff-reviewed versions.",
    "category": "resource-management",
    "audiences": [
      "resource owner",
      "resource staff",
      "admin"
    ],
    "visibility": "public",
    "reviewedAt": "2026-10-02",
