    "id": "HC-45",
    "slug": "understand-coordination-groups-versus-public-resource-groups",
    "title": "Understand coordination groups versus public Resource Groups",
    "summary": "Review coordination groups and their access rules separately from public Resource Groups.",
    "category": "organisation-governance",
    "audiences": [
      "organisation staff",
      "organisation admin",
      "super admin"
    ],
    "visibility": "organization",
    "reviewedAt": "2026-10-02",
